/**
 * Generic, security-aware record search used by the admin "record finder" UI.
 * Runs exactly one SOQL query, enforcing the running user's object/field
 * permissions and record sharing, and is safe against SOQL injection.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ----- Object validation -----
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }

        SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sobjType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        DescribeSObjectResult objDesc = sobjType.getDescribe();
        if (!objDesc.isAccessible()) {
            throw new SearchException('Insufficient access to read object: ' + objDesc.getName());
        }

        // ----- Basic argument validation -----
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field is required.');
        }

        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // Build a case-insensitive lookup of the object's fields.
        Map<String, SObjectField> rawFieldMap = objDesc.fields.getMap();
        Map<String, SObjectField> fieldMap = new Map<String, SObjectField>();
        for (String key : rawFieldMap.keySet()) {
            fieldMap.put(key.toLowerCase(), rawFieldMap.get(key));
        }

        // ----- SELECT list -----
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> added = new Set<String>{ 'id' };

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('A requested field name is blank.');
            }
            SObjectField sf = fieldMap.get(f.toLowerCase());
            if (sf == null) {
                throw new SearchException('Unknown field: ' + f);
            }
            DescribeFieldResult dfr = sf.getDescribe();
            if (!dfr.isAccessible()) {
                throw new SearchException('Insufficient access to read field: ' + dfr.getName());
            }
            String canonical = dfr.getName();
            if (!added.contains(canonical.toLowerCase())) {
                added.add(canonical.toLowerCase());
                selectFields.add(canonical);
            }
        }

        // ----- WHERE clause -----
        List<String> whereClauses = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        Integer bindIndex = 0;

        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                if (String.isBlank(key)) {
                    throw new SearchException('A filter field name is blank.');
                }
                SObjectField sf = fieldMap.get(key.toLowerCase());
                if (sf == null) {
                    throw new SearchException('Unknown filter field: ' + key);
                }
                DescribeFieldResult dfr = sf.getDescribe();
                if (!dfr.isAccessible()) {
                    throw new SearchException('Insufficient access to read field: ' + dfr.getName());
                }
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                }
                String bindName = 'bind' + bindIndex;
                whereClauses.add(dfr.getName() + ' = :' + bindName);
                binds.put(bindName, filters.get(key));
                bindIndex++;
            }
        }

        // ----- ORDER BY -----
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            SObjectField sf = fieldMap.get(orderByField.toLowerCase());
            if (sf == null) {
                throw new SearchException('Unknown order-by field: ' + orderByField);
            }
            DescribeFieldResult dfr = sf.getDescribe();
            if (!dfr.isAccessible()) {
                throw new SearchException('Insufficient access to read field: ' + dfr.getName());
            }
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + dfr.getName());
            }
            orderByClause = ' ORDER BY ' + dfr.getName() + ' ASC';
        }

        // ----- Assemble the single SOQL query -----
        String soql = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + objDesc.getName();

        if (!whereClauses.isEmpty()) {
            soql += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        soql += orderByClause;
        soql += ' LIMIT ' + maxRows;

        // Execute in USER_MODE so FLS and record sharing are enforced,
        // and values are bound (never concatenated) to prevent injection.
        try {
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }
}
