```apex
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null) {
            return results;
        }

        // Collect the normalized emails we actually need to look up.
        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            String norm = normalize(req == null ? null : req.email);
            if (norm != null) {
                normalizedEmails.add(norm);
            }
        }

        // Build a map of normalized email -> earliest created contact Id.
        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            // Order by CreatedDate ASC so the first occurrence we store is the earliest.
            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC
            ]) {
                String key = normalize(c.Email);
                if (key != null && !emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        // Produce exactly one Result per Request, preserving order.
        for (Request req : requests) {
            Result res = new Result();
            String norm = normalize(req == null ? null : req.email);
            Id matchId = (norm == null) ? null : emailToContactId.get(norm);
            res.contactId = matchId;
            res.found = (matchId != null);
            results.add(res);
        }

        return results;
    }

    private static String normalize(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (String.isBlank(trimmed)) {
            return null;
        }
        return trimmed.toLowerCase();
    }
}
