public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();
        order.total = 0;
        order.lines = new List<Line>();

        // number (required, non-blank)
        Object numObj = root.get('number');
        String number = (numObj == null) ? null : String.valueOf(numObj);
        if (String.isBlank(number)) {
            throw new PayloadException('Missing or blank number.');
        }
        order.orderNumber = number;

        // date
        Object dateObj = root.get('date');
        if (dateObj != null) {
            String dateStr = String.valueOf(dateObj);
            if (String.isNotBlank(dateStr)) {
                order.orderDate = Date.valueOf(dateStr);
            }
        }

        // currency
        Object currObj = root.get('currency');
        if (currObj != null) {
            order.currencyCode = String.valueOf(currObj);
        }

        // customer.email
        Object custObj = root.get('customer');
        if (custObj instanceof Map<String, Object>) {
            Map<String, Object> customer = (Map<String, Object>) custObj;
            Object emailObj = customer.get('email');
            if (emailObj != null) {
                order.customerEmail = String.valueOf(emailObj);
            }
        }

        // lines
        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('lines is not a JSON array.');
            }
            List<Object> rawLines = (List<Object>) linesObj;
            for (Object rawLine : rawLines) {
                if (!(rawLine instanceof Map<String, Object>)) {
                    throw new PayloadException('A line is not a JSON object.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) rawLine;
                Line line = parseLine(lineMap);
                order.lines.add(line);
                order.total = order.total + line.lineTotal;
            }
        }

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // sku (required)
        Object skuObj = lineMap.get('sku');
        String sku = (skuObj == null) ? null : String.valueOf(skuObj);
        if (String.isBlank(sku)) {
            throw new PayloadException('Line is missing sku.');
        }
        line.sku = sku;

        // quantity (required, positive)
        Object qtyObj = lineMap.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Line is missing quantity.');
        }
        Decimal qtyDec = toDecimal(qtyObj);
        if (qtyDec == null || qtyDec <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        line.quantity = qtyDec.intValue();

        // unitPrice (required, non-negative)
        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Line is missing unitPrice.');
        }
        Decimal unitPrice = toDecimal(priceObj);
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Line unitPrice must be non-negative.');
        }
        line.unitPrice = unitPrice;

        // discount (optional, default 0)
        Object discObj = lineMap.get('discount');
        Decimal discount = (discObj == null) ? 0 : toDecimal(discObj);
        if (discount == null) {
            discount = 0;
        }
        line.discount = discount;

        // lineTotal = quantity * unitPrice * (1 - discount), rounded half up to 2 dp
        Decimal raw = qtyDec * unitPrice * (1 - discount);
        line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object o) {
        if (o == null) {
            return null;
        }
        if (o instanceof Decimal) {
            return (Decimal) o;
        }
        if (o instanceof Integer) {
            return Decimal.valueOf((Integer) o);
        }
        if (o instanceof Long) {
            return Decimal.valueOf((Long) o);
        }
        if (o instanceof Double) {
            return Decimal.valueOf(String.valueOf((Double) o));
        }
        try {
            return Decimal.valueOf(String.valueOf(o));
        } catch (Exception e) {
            return null;
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', order.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', order.lines == null ? 0 : order.lines.size());
        gen.writeNumberField('total', order.total == null ? 0 : order.total);
        gen.writeEndObject();
        return gen.getAsString();
    }
}
