    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        // Resolve the object (case-insensitive).
        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sobjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        // Resolve the field (case-insensitive).
        Map<String, Schema.SObjectField> fieldMap = sobjType.getDescribe().fields.getMap();
        Schema.SObjectField field = fieldMap.get(fieldApiName.trim().toLowerCase());
        if (field == null) {
            throw new PicklistServiceException(
                'Field does not exist on object ' + objectApiName + ': ' + fieldApiName
            );
        }

        Schema.DescribeFieldResult dfr = field.getDescribe();
        Schema.DisplayType fieldType = dfr.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldApiName
            );
        }

        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : dfr.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new PicklistService.Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }
        return options;
    }
}
