```apex
public with sharing class AccountScoringJob implements Queueable {

    // Maximum number of accounts processed per execution (and chain step).
    @TestVisible
    private static final Integer BATCH_SIZE = 200;

    private final List<Id> accountIds;

    /**
     * Constructor.
     * @param accountIds Account Ids to process. A null value is treated as an empty list.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    /**
     * Enqueues the first job of the chain.
     * @param accountIds Account Ids to re-rate.
     * @return The enqueued job Id, or null when there is nothing to do.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Processes the first (at most) BATCH_SIZE Ids of this job, then chains the rest.
     * One SOQL query and one DML statement per execution.
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer currentBatchSize = Math.min(BATCH_SIZE, accountIds.size());

        // First currentBatchSize Ids become this execution's batch.
        List<Id> batchIds = new List<Id>();
        for (Integer i = 0; i < currentBatchSize; i++) {
            batchIds.add(accountIds[i]);
        }

        // One SOQL query.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            acc.Rating = rate(acc.AnnualRevenue);
        }

        // One DML statement.
        update accounts;

        // Chain the remaining Ids, if any.
        if (accountIds.size() > currentBatchSize) {
            List<Id> remaining = new List<Id>();
            for (Integer i = currentBatchSize; i < accountIds.size(); i++) {
                remaining.add(accountIds[i]);
            }
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    /**
     * Rating rules: >= 1,000,000 -> Hot; >= 100,000 -> Warm; otherwise (incl. blank) -> Cold.
     */
    private static String rate(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        } else if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }
}
