public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point from the trigger. Works out which accounts could be affected
     * by the current DML and recalculates their open-pipeline fields.
     */
    public static void handle(
        TriggerOperation op,
        Map<Id, Opportunity> oldMap,
        Map<Id, Opportunity> newMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        switch on op {
            when AFTER_INSERT {
                for (Opportunity o : newMap.values()) {
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                }
            }
            when AFTER_UPDATE {
                for (Opportunity o : newMap.values()) {
                    Opportunity old = oldMap.get(o.Id);
                    // Only care about changes that can move the totals:
                    // amount changes, open/closed changes, or a reparent.
                    if (o.AccountId != old.AccountId
                        || o.Amount != old.Amount
                        || o.IsClosed != old.IsClosed) {
                        if (o.AccountId != null) {
                            accountIds.add(o.AccountId);
                        }
                        if (old.AccountId != null) {
                            accountIds.add(old.AccountId);
                        }
                    }
                }
            }
            when AFTER_DELETE {
                for (Opportunity o : oldMap.values()) {
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                }
            }
            when AFTER_UNDELETE {
                for (Opportunity o : newMap.values()) {
                    if (o.AccountId != null) {
                        accountIds.add(o.AccountId);
                    }
                }
            }
            when else {
                // Nothing to do for other operations.
            }
        }

        recalculate(accountIds);
    }

    /**
     * Recalculates FB_Open_Pipeline__c and FB_Open_Opportunities__c for the
     * supplied accounts and only writes the ones whose values actually change.
     *
     * The "only update when changed" behaviour is what makes this safe against
     * the legacy AccountTrigger: updating an account causes that trigger to run
     * and update the account's open opportunities, which re-fires this trigger.
     * Because the second pass finds the totals already correct it performs no
     * DML, so the chain terminates instead of recursing forever.
     */
    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Default every account to 0 / 0 so that an account whose last open
        // opportunity has gone away is reset rather than left blank.
        Map<Id, Decimal> sums = new Map<Id, Decimal>();
        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (Id aId : accountIds) {
            sums.put(aId, 0);
            counts.put(aId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId aid, COUNT(Id) cnt, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id aId = (Id) ar.get('aid');
            counts.put(aId, (Integer) ar.get('cnt'));
            Decimal total = (Decimal) ar.get('total');
            sums.put(aId, total == null ? 0 : total);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newSum = sums.get(acc.Id);
            Integer newCount = counts.get(acc.Id);

            if (acc.FB_Open_Pipeline__c != newSum
                || acc.FB_Open_Opportunities__c != newCount) {
                acc.FB_Open_Pipeline__c = newSum;
                acc.FB_Open_Opportunities__c = newCount;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
