public with sharing class LogPurgeJob implements Schedulable {

    // No-argument constructor (provided implicitly, declared for clarity)
    public LogPurgeJob() {}

    /**
     * Scheduled entry point. Deletes old integration logs:
     *  - Non-ERROR logs older than 30 days.
     *  - ERROR logs older than 180 days.
     */
    public void execute(SchedulableContext sc) {
        purge();
    }

    /**
     * Performs the deletion. Uses relative date literals so the comparison is
     * always evaluated against "now". Null / blank Level__c values are treated
     * as non-ERROR (null != 'ERROR' evaluates to true in SOQL).
     */
    public static void purge() {
        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < LAST_N_DAYS:30)
               OR (CreatedDate < LAST_N_DAYS:180)
        ];

        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, false);
        }
    }

    /**
     * Schedules this job to run every night at 02:00.
     * @return the CronTrigger Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Seconds Minutes Hours Day-of-month Month Day-of-week
        String cron = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cron, new LogPurgeJob());
    }
}
