@IsTest
private class OpportunitiesServiceTest {

    // Small bundle to hold the configured mocks for a test.
    private class MockBundle {
        fflib_ApexMocks mocks;
        IOpportunities domainMock;
        IOpportunitiesSelector selectorMock;
        fflib_ISObjectUnitOfWork uowMock;
    }

    // Creates ApexMocks, stubs the identity methods fflib needs for mock registration,
    // and injects the mocks through the Application factories.
    private static MockBundle setupMocks() {
        MockBundle b = new MockBundle();
        b.mocks = new fflib_ApexMocks();
        b.domainMock = (IOpportunities) b.mocks.mock(IOpportunities.class);
        b.selectorMock = (IOpportunitiesSelector) b.mocks.mock(OpportunitiesSelector.class);
        b.uowMock = (fflib_ISObjectUnitOfWork) b.mocks.mock(fflib_ISObjectUnitOfWork.class);

        b.mocks.startStubbing();
        b.mocks.when(b.domainMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        b.mocks.when(b.selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        b.mocks.stopStubbing();

        Application.Domain.setMock(b.domainMock);
        Application.Selector.setMock(b.selectorMock);
        Application.UnitOfWork.setMock(b.uowMock);
        return b;
    }

    // Asserts that nothing (selector, domain, uow) is exercised.
    private static void assertNothingHappened(MockBundle b) {
        ((IOpportunitiesSelector) b.mocks.verify(b.selectorMock, fflib_ApexMocks.NEVER))
            .selectById((Set<Id>) fflib_Match.anyObject());
        ((IOpportunities) b.mocks.verify(b.domainMock, fflib_ApexMocks.NEVER))
            .applyDiscount(fflib_Match.anyDecimal(), (fflib_ISObjectUnitOfWork) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) b.mocks.verify(b.uowMock, fflib_ApexMocks.NEVER)).commitWork();
    }

