    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        fflib_QueryFactory query = newQueryFactory()
            .selectField('Account.Name')
            .setCondition('AccountId IN :accountIds AND IsClosed = false')
            // Highest Amount first, Amount nulls after the others, then earliest CloseDate.
            .setOrdering('Amount', fflib_QueryFactory.SortOrder.DESCENDING, true)
            .addOrdering('CloseDate', fflib_QueryFactory.SortOrder.ASCENDING, false)
            .setLimit(maxRecords);

        return (List<Opportunity>) Database.query(query.toSOQL());
    }
