```apex
public with sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    private static final String RATING_HOT  = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    /**
     * Future entry point. Takes a Set<Id> rather than a single Id so that a
     * batch of 200 opportunities results in ONE future call, not 200.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        recalculateSync(accountIds);
    }

    /**
     * Core logic, kept synchronous and separate so it is easy to unit test
     * without dealing with future-call boundaries.
     */
    public static void recalculateSync(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Start every account at Cold; open opportunities will upgrade it.
        Map<Id, String> ratingByAccount = new Map<Id, String>();
        for (Id accId : accountIds) {
            ratingByAccount.put(accId, RATING_COLD);
        }

        // Only open opportunities count towards the pipeline rating.
        for (Opportunity opp : [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            WITH USER_MODE
        ]) {
            String current = ratingByAccount.get(opp.AccountId);

            // Once Hot, it stays Hot.
            if (current == RATING_HOT) {
                continue;
            }

            if (opp.Amount != null && opp.Amount >= HOT_THRESHOLD) {
                ratingByAccount.put(opp.AccountId, RATING_HOT);
            } else {
                // Has an open opp but not a big one -> at least Warm.
                ratingByAccount.put(opp.AccountId, RATING_WARM);
            }
        }

        // Build the updates, skipping accounts whose rating is already correct.
        Map<Id, Account> currentAccounts = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
            WITH USER_MODE
        ]);

        List<Account> toUpdate = new List<Account>();
        for (Id accId : ratingByAccount.keySet()) {
            Account existing = currentAccounts.get(accId);
            if (existing == null) {
                continue; // account was deleted in the meantime
            }

            String newRating = ratingByAccount.get(accId);
            if (existing.Rating != newRating) {
                toUpdate.add(new Account(Id = accId, Rating = newRating));
            }
        }

        if (!toUpdate.isEmpty()) {
            update as user toUpdate;
        }
    }
}
```

A couple of notes on choices: I derive "open" from the standard `IsClosed` flag rather than hard-coding stage names, so it respects your org's stage configuration. I enforce `WITH USER_MODE` / `update as user` for FLS/CRUD safety, and I skip no-op updates to avoid pointless DML and recursive churn. If you'd rather the rating ignore the running user's sharing/FLS and always reflect the full pipeline, switch those to `SYSTEM_MODE` and plain `update`.

