```apex
trigger CaseTrigger on Case (after update) {

    // Collect cases that just transitioned from not-closed to closed and
    // that have a contact (cases without a contact get no survey task).
    List<Id> newlyClosedWithContact = new List<Id>();
    for (Case c : Trigger.new) {
        Case prior = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !prior.IsClosed && c.ContactId != null) {
            newlyClosedWithContact.add(c.Id);
        }
    }

    if (newlyClosedWithContact.isEmpty()) {
        return;
    }

    // System.enqueueJob can be called at most 50 times per transaction. A
    // nightly cleanup can close up to 200 cases at once, so enqueuing one job
    // per case directly would blow the limit. We enqueue individual jobs while
    // we have budget and hand any overflow to the last job, which chains the
    // remainder one case at a time. Every case is still processed in its own
    // Queueable execution, so one failure cannot affect the others.
    Integer budget = Limits.getLimitQueueableJobs() - Limits.getQueueableJobs();

    if (newlyClosedWithContact.size() <= budget) {
        for (Id caseId : newlyClosedWithContact) {
            System.enqueueJob(new CaseSurveyJob(caseId));
        }
    } else {
        List<Id> overflow = new List<Id>();
        for (Integer i = 0; i < newlyClosedWithContact.size(); i++) {
            if (i < budget - 1) {
                // Leave one slot for the chaining job below.
                System.enqueueJob(new CaseSurveyJob(newlyClosedWithContact[i]));
            } else {
                overflow.add(newlyClosedWithContact[i]);
            }
        }
        Id first = overflow.remove(0);
        System.enqueueJob(new CaseSurveyJob(first, overflow));
    }
}
