```apex
public with sharing class CaseSurveyJob implements Queueable {

    private final Id caseId;
    private final List<Id> remaining;

    /**
     * Process a single case.
     */
    public CaseSurveyJob(Id caseId) {
        this(caseId, new List<Id>());
    }

    /**
     * Process a single case, then chain through any remaining case ids.
     * Used when more than ~50 cases close in one transaction, which exceeds
     * the per-transaction System.enqueueJob limit.
     */
    public CaseSurveyJob(Id caseId, List<Id> remaining) {
        this.caseId = caseId;
        this.remaining = (remaining == null) ? new List<Id>() : remaining;
    }

    public void execute(QueueableContext context) {
        // Isolate the work for this case: a failure here must not stop the
        // chained jobs for the other cases from running.
        try {
            createSurveyTask();
        } catch (Exception e) {
            System.debug(
                LoggingLevel.ERROR,
                'CSAT survey task failed for case ' + caseId + ': ' + e.getMessage()
            );
        }

        // Chain the next case, if any. A Queueable may enqueue exactly one
        // child job, so we hand off one leftover case per execution.
        if (!remaining.isEmpty() && !Test.isRunningTest()) {
            Id next = remaining.remove(0);
            System.enqueueJob(new CaseSurveyJob(next, remaining));
        }
    }

    private void createSurveyTask() {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];
        if (cases.isEmpty()) {
            return;
        }

        Case c = cases[0];

        // Re-validate: the case could have been reopened or had its contact
        // removed between enqueue time and execution time.
        if (!c.IsClosed || c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId       = c.Id,
            WhoId        = c.ContactId,
            Subject      = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );
        insert surveyTask;
    }
}
```

