public with sharing class AccountCountrySync {

    /**
     * When an Account's BillingCountry changes, push the new value onto the
     * MailingCountry of its contacts whose MailingCountry is blank or equal to
     * the account's previous BillingCountry. Contacts that live abroad (any other
     * MailingCountry) and contacts of unchanged accounts are left alone.
     *
     * One SOQL query, no queries inside loops.
     */
    public static void syncContactCountries(
        Map<Id, Account> oldMap,
        Map<Id, Account> newMap
    ) {
        // 1. Work out which accounts actually changed BillingCountry, and remember
        //    the old value so we know which contacts are "still following HQ".
        Map<Id, String> oldCountryByAccount = new Map<Id, String>();
        Map<Id, String> newCountryByAccount = new Map<Id, String>();

        for (Account newAcc : newMap.values()) {
            String oldCountry = oldMap.get(newAcc.Id).BillingCountry;
            String newCountry = newAcc.BillingCountry;

            if (!equalsNullSafe(oldCountry, newCountry)) {
                oldCountryByAccount.put(newAcc.Id, oldCountry);
                newCountryByAccount.put(newAcc.Id, newCountry);
            }
        }

        // Nothing changed? Then there is nothing to do.
        if (newCountryByAccount.isEmpty()) {
            return;
        }

        // 2. Load the relevant contacts once. Filtered to the changed accounts so
        //    this stays within SOQL row / heap limits even in a 2.3M-contact org.
        Set<Id> changedAccountIds = newCountryByAccount.keySet();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            String oldCountry = oldCountryByAccount.get(con.AccountId);
            String newCountry = newCountryByAccount.get(con.AccountId);

            Boolean mailingIsBlank = String.isBlank(con.MailingCountry);
            Boolean followedHq = equalsNullSafe(con.MailingCountry, oldCountry);

            if (mailingIsBlank || followedHq) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
            // else: contact works abroad -> leave alone.
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    /**
     * Null-safe string comparison. Treats two nulls as equal and null vs a value
     * as not equal.
     */
    private static Boolean equalsNullSafe(String a, String b) {
        if (a == null) {
            return b == null;
        }
        return a.equals(b);
    }
}
