```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    _debounceTimeout;
    _latestRequestId = 0;
    _isConnected = true;

    disconnectedCallback() {
        // Component removed from the page: prevent any pending search from running
        this._isConnected = false;
        this.clearPendingSearch();
    }

    clearPendingSearch() {
        if (this._debounceTimeout) {
            clearTimeout(this._debounceTimeout);
            this._debounceTimeout = undefined;
        }
    }

    handleChange(event) {
        const searchTerm = event.target.value.trim();

        // Always cancel any pending search; we have a newer value
        this.clearPendingSearch();

        if (searchTerm.length < 2) {
            // Too short: do not call Apex, clear results, invalidate in-flight responses
            this._latestRequestId++;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimeout = setTimeout(() => {
            this._debounceTimeout = undefined;
            this.runSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    runSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._latestRequestId;

        searchContacts({ searchTerm })
            .then((result) => {
                // Ignore if the component is gone or this is a stale response
                if (!this._isConnected || requestId !== this._latestRequestId) {
                    return;
                }
                this.contacts = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isConnected || requestId !== this._latestRequestId) {
                    return;
                }
                this.contacts = [];
                this.error = error;
            });
    }

    get errorMessage() {
        return this.error && this.error.body ? this.error.body.message : '';
    }
}
