import { LightningElement, api, track } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity }. */
    @api lines = [];

    @track showError = false;

    get editors() {
        return Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );
    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        // Validate every editor so all invalid lines show their errors at once.
        let allValid = true;
        this.editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.showError = true;
            return;
        }

        this.showError = false;
        const lines = this.editors.map((editor) => editor.getValue());
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines }
            })
        );
    }
}
