import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    getInput(field) {
        return this.template.querySelector(`[data-field="${field}"]`);
    }

    async handleRegister() {
        // Step 1: validate email domain
        const emailInput = this.getInput('email');
        const domain = (this.email || '').split('@')[1];
        if (domain && BLOCKED_DOMAINS.includes(domain.toLowerCase())) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on every input
        const inputs = this.template.querySelectorAll('lightning-input[data-field]');
        let allValid = true;
        inputs.forEach((input) => {
            const valid = input.reportValidity();
            if (!valid) {
                allValid = false;
            }
        });

        // Step 3: stop if invalid
        if (!allValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
}
