import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value = '';
    _activeValue = '';

    @api
    get value() {
        return this._value;
    }
    set value(v) {
        this._value = v || '';
        // When the parent changes the selection, the active option moves to it.
        this._activeValue = this._value;
    }

    // Effective active value: the stored one if valid, otherwise a sensible default.
    get activeValue() {
        const opts = this.options || [];
        if (this._activeValue && opts.some((o) => o.value === this._activeValue)) {
            return this._activeValue;
        }
        if (this._value && opts.some((o) => o.value === this._value)) {
            return this._value;
        }
        return opts.length ? opts[0].value : '';
    }

    get computedOptions() {
        const selected = this._value;
        return (this.options || []).map((o, i) => ({
            value: o.value,
            label: o.label,
            id: `option-${i}`,
            selected: o.value === selected ? 'true' : 'false'
        }));
    }

    get activeDescendant() {
        const opts = this.options || [];
        const active = this.activeValue;
        const i = opts.findIndex((o) => o.value === active);
        return i >= 0 ? `option-${i}` : null;
    }

    handleKeydown(event) {
        const opts = this.options || [];
        if (!opts.length) {
            return;
        }
        let i = opts.findIndex((o) => o.value === this.activeValue);
        if (i < 0) {
            i = 0;
        }
        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (i < opts.length - 1) {
                    this._activeValue = opts[i + 1].value;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (i > 0) {
                    this._activeValue = opts[i - 1].value;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeValue = opts[0].value;
                break;
            case 'End':
                event.preventDefault();
                this._activeValue = opts[opts.length - 1].value;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectValue(this.activeValue);
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour.
                break;
        }
    }

    handleClick(event) {
        const v = event.currentTarget.dataset.value;
        this._activeValue = v;
        this.selectValue(v);
    }

    selectValue(v) {
        if (v === this._value) {
            return;
        }
        this._value = v;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: v } }));
    }
}
