/**
 * Service for setting a donor's current employer as their primary NPSP Affiliation.
 *
 * Relies on NPSP's standard Affiliation management: changing a Contact's
 * npsp__Primary_Affiliation__c lookup causes the NPSP Affiliations trigger
 * (AFFL_Affiliations_TDTM) to:
 *   - create a Current, primary Affiliation to the new Organization, and
 *   - mark the prior primary Affiliation as Former, non-primary with EndDate = today.
 *
 * Because we delegate to that standard mechanism, this method itself uses only
 * 1 SOQL query and 1 DML statement (well within the 2/2 budget), and is bulk-safe
 * for 200+ contacts in a single call.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // A null or empty map does nothing.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Query current state so we can skip contacts whose primary affiliation
        // already points at the requested organization (no duplicate affiliation).
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ]) {
            Id desiredOrgId = employerByContactId.get(c.Id);
            if (desiredOrgId == null) {
                continue;
            }

            // Only change contacts whose employer is actually different.
            // Contact stays in their household account; we only touch the lookup.
            if (c.npsp__Primary_Affiliation__c != desiredOrgId) {
                c.npsp__Primary_Affiliation__c = desiredOrgId;
                contactsToUpdate.add(c);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // Updating the primary affiliation lookup triggers NPSP to create the
            // new Current/primary Affiliation and retire the former one.
            update contactsToUpdate;
        }
    }
}
