/**
 * Records monthly recurring gifts as NPSP Enhanced Recurring Donations (RD2).
 *
 * Bulk-safe: validates the whole batch before any DML, then performs a single
 * insert. NPSP's own triggers generate the installment Opportunities, so this
 * service never creates Opportunity records itself.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    // RD2 Day-of-Month picklist value representing the last day of the month.
    private static final String DAY_OF_MONTH_LAST_DAY = 'Last_Day';

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> resultIds = new List<Id>();

        // A null or empty list simply returns an empty list.
        if (requests == null || requests.isEmpty()) {
            return resultIds;
        }

        // Validate the entire batch before performing any DML.
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Gift request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('A donor contact is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be a positive value.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('A start date is required.');
            }
        }

        // Build all Enhanced Recurring Donations.
        List<npe03__Recurring_Donation__c> recurringDonations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor and amount.
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;

            // Monthly schedule (RD2 period + frequency).
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npsp__InstallmentFrequency__c = 1;

            // Dates and status.
            rd.npsp__StartDate__c = req.startDate;
            rd.npe03__Date_Established__c = req.startDate;
            rd.npsp__Status__c = 'Active';

            // Payment method.
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            // Day of month: "31" means last day of the month; 29/30 stored as-is.
            if (req.dayOfMonth == 31) {
                rd.npsp__Day_of_Month__c = DAY_OF_MONTH_LAST_DAY;
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
            } else {
                rd.npsp__Day_of_Month__c = String.valueOf(req.dayOfMonth);
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
            }

            // Open-ended vs. fixed-length.
            if (req.installments == null || req.installments == 0) {
                rd.npsp__RecurringType__c = 'Open';
            } else {
                rd.npsp__RecurringType__c = 'Fixed';
                rd.npe03__Installments__c = req.installments;
            }

            recurringDonations.add(rd);
        }

        // Single DML statement. NPSP generates the installment Opportunities.
        insert recurringDonations;

        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            resultIds.add(rd.Id);
        }

        return resultIds;
    }
}
