public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // --- Validate inputs before touching any data ---
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation percentage must be provided.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Ids cannot be null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Every percentage must be greater than 0.');
            }
            total += pct;
        }

        if (total > 100) {
            throw new AllocationException('The percentages add up to ' + total + '%, which is more than 100%.');
        }

        // Verify that every referenced GAU exists and is active.
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit ' + gauId + ' does not exist.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit "' + gau.Name + '" is inactive.');
            }
        }

        // --- Validation complete: now mutate data ---

        // Remove all existing GAU allocations for this opportunity.
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        // Build one percent-based allocation per map entry.
        // Using npsp__Percent__c (not npsp__Amount__c) keeps the allocations
        // correct automatically whenever the Opportunity amount changes.
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            toInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert toInsert;

        return toInsert;
    }
}
