public with sharing class HouseholdService {

    /**
     * Registers a new family as a single NPSP Household Account.
     *
     * All supplied contacts (which must be new - no Id, no AccountId) are inserted
     * into ONE new NPSP Household account. NPSP itself creates the household,
     * assigns the "HH_Account" record type, names it and generates greetings, so we
     * never set the account name or hard-code a record type Id. The first contact in
     * the list is made the household's primary contact.
     *
     * @param members the new contacts to place in the household (first = primary)
     * @return the Id of the single household Account created
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // 1. Insert the first contact on its own. Because this org runs the NPSP
        //    Household Account model, NPSP's trigger handlers create exactly one new
        //    Household account (HH_Account record type) for this contact, set it as
        //    the primary (npe01__One2OneContact__c), name it and build greetings.
        Contact primary = members[0];
        insert primary;

        // Re-query to obtain the household Account Id that NPSP assigned.
        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primary.Id
            LIMIT 1
        ].AccountId;

        // 2. Attach every remaining contact to that same household. Since AccountId
        //    is already populated, NPSP does NOT create additional households; it
        //    simply adds them as members and refreshes the household name/greetings.
        if (members.size() > 1) {
            List<Contact> others = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact c = members[i];
                c.AccountId = householdId;
                others.add(c);
            }
            insert others;
        }

        // 3. Guarantee the first contact is the household's primary contact.
        update new Account(
            Id = householdId,
            npe01__One2OneContact__c = primary.Id
        );

        return householdId;
    }
}
