public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static String keyOf(Id oppId, Id contactId) {
        return String.valueOf(oppId) + '|' + String.valueOf(contactId);
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect ids
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            oppIds.add(r.opportunityId);
            contactIds.add(r.contactId);
        }

        // SOQL 1: Opportunities (for validation)
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // Validate everything BEFORE any DML
        for (SoftCreditRequest r : requests) {
            Opportunity opp = oppMap.get(r.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + r.opportunityId);
            }
            if (r.contactId != null && r.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + r.contactId + ' is the primary contact on opportunity ' + r.opportunityId);
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be a positive value for opportunity ' + r.opportunityId);
            }
            if (opp.Amount == null || r.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount exceeds the opportunity amount for opportunity ' + r.opportunityId);
            }
        }

        // SOQL 2: existing Opportunity Contact Roles for these opp/contact pairs
        Map<String, List<OpportunityContactRole>> ocrByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String k = keyOf(ocr.OpportunityId, ocr.ContactId);
            if (!ocrByKey.containsKey(k)) {
                ocrByKey.put(k, new List<OpportunityContactRole>());
            }
            ocrByKey.get(k).add(ocr);
        }

        // SOQL 3: existing Partial Soft Credits for these opp/contact pairs
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String k = keyOf(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            // Keep the first one found per pair (pairs are unique in a call anyway)
            if (!pscByKey.containsKey(k)) {
                pscByKey.put(k, psc);
            }
        }

        // Determine the single OCR each contact should end up with
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> chosenOcrByKey =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest r : requests) {
            String k = keyOf(r.opportunityId, r.contactId);
            List<OpportunityContactRole> existing = ocrByKey.get(k);
            OpportunityContactRole chosen;

            if (existing == null || existing.isEmpty()) {
                chosen = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId     = r.contactId,
                    Role          = r.role
                );
            } else {
                // Reuse the first existing role, align its Role, remove any extras
                chosen = existing[0];
                chosen.Role = r.role;
                for (Integer i = 1; i < existing.size(); i++) {
                    ocrsToDelete.add(existing[i]);
                }
            }

            ocrsToUpsert.add(chosen);
            chosenOcrByKey.put(k, chosen);
        }

        // DML 1: upsert the contact roles (inserts get their Ids populated)
        upsert ocrsToUpsert;

        // DML 2: delete any surplus contact roles so exactly one remains
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // Build / update the partial soft credits
        List<npsp__Partial_Soft_Credit__c> pscToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest r : requests) {
            String k = keyOf(r.opportunityId, r.contactId);
            OpportunityContactRole chosen = chosenOcrByKey.get(k);

            npsp__Partial_Soft_Credit__c psc = pscByKey.get(k);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c     = r.contactId
                );
            }
            psc.npsp__Amount__c         = r.amount;
            psc.npsp__Role_Name__c      = r.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(chosen.Id);

            pscToUpsert.add(psc);
        }

        // DML 3: upsert the partial soft credits
        if (!pscToUpsert.isEmpty()) {
            upsert pscToUpsert;
        }
    }
}
