public with sharing class FamilyService {

    /**
     * Records in NPSP that each parent is the child's "Parent".
     *
     * We only insert the child -> parent relationship (Type = 'Parent', Status = 'Current').
     * NPSP's TDTM relationship trigger automatically creates the reciprocal record on the
     * parent (Son / Daughter / Child, based on the child's gender and the configured
     * Relationship Lookup), so we never create the reverse record ourselves.
     *
     * @param parentIdByChildId key = child Contact Id, value = parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null / empty input does nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Gather every Contact Id involved so we can look up existing relationships in one query.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null && childId != parentId) {
                contactIds.add(childId);
                contactIds.add(parentId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        // Single SOQL: find any relationship that already exists between contacts in our set.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE npe4__Contact__c IN :contactIds
                  AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Build the new child -> parent "Parent" relationships, skipping any pair that
        // already has a relationship in either direction (or a duplicate within this batch).
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String forward = pairKey(childId, parentId);
            String reverse = pairKey(parentId, childId);

            if (existingPairs.contains(forward) || existingPairs.contains(reverse)) {
                continue;
            }

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = 'Parent',
                npe4__Status__c         = 'Current'
            ));

            // Guard against duplicate pairs supplied within this same call.
            existingPairs.add(forward);
            existingPairs.add(reverse);
        }

        // Single DML of our own. NPSP's trigger creates the reciprocal record automatically.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Directional key for a pair of contacts.
     */
    private static String pairKey(Id contactId, Id relatedContactId) {
        return String.valueOf(contactId) + '|' + String.valueOf(relatedContactId);
    }
}
