public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // Respect object-level read access; if the user can't read the
        // object at all, return an empty list.
        if (!Schema.sObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // "with sharing" on the class enforces record-level sharing.
        List<FB_Employee__c> records = [
            SELECT Id, Name, Department__c, Salary__c, Personal_Email__c
            FROM FB_Employee__c
            ORDER BY Name ASC
        ];

        // Remove any fields the running user cannot read. stripInaccessible
        // drops inaccessible fields from the records entirely (they are not
        // present, rather than being nulled out) and never throws for FLS.
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            records
        );

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
