/**
 * Service for importing legacy contacts.
 *
 * Legacy contacts are existing customers, so the "Send welcome pack" task
 * (created by the TA_Contact_CreateWelcomeTask after-insert action) must be
 * skipped for them, while all other Contact automation (such as the
 * TA_Contact_FormatPhone before-insert action) still runs.
 */
public with sharing class ContactImportService {
    @TestVisible
    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the given contacts in a single DML statement with the
     * TA_Contact_CreateWelcomeTask action bypassed. The bypass is cleared
     * before the method returns so that contacts inserted later in the same
     * transaction still receive their welcome task.
     *
     * @param contacts the contacts to insert
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Remember whether the action was already bypassed so we can restore
        // the exact prior state rather than blindly clearing it.
        Boolean alreadyBypassed = MetadataTriggerHandler.isBypassed(WELCOME_TASK_ACTION);

        if (!alreadyBypassed) {
            MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION);
        }

        try {
            insert contacts;
        } finally {
            if (!alreadyBypassed) {
                MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION);
            }
        }
    }
}
