/**
 * Trigger action that prevents two Contacts on the same Account from sharing an
 * email address (case-insensitive). Runs on before insert and before update.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        enforce((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        enforce((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void enforce(List<Contact> newList, List<Contact> oldList) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (oldList != null) {
            for (Contact oldCon : oldList) {
                oldById.put(oldCon.Id, oldCon);
            }
        }

        // Determine which contacts actually need checking.
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> newIds = new Set<Id>();

        for (Contact con : newList) {
            if (con.Id != null) {
                newIds.add(con.Id);
            }
            if (con.AccountId == null || String.isBlank(con.Email)) {
                continue;
            }
            if (oldList != null) {
                Contact oldCon = oldById.get(con.Id);
                Boolean emailChanged = oldCon == null
                    ? true
                    : con.Email != oldCon.Email;
                Boolean accountChanged = oldCon == null
                    ? true
                    : con.AccountId != oldCon.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }
            candidates.add(con);
            accountIds.add(con.AccountId);
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Build the set of existing account/email keys already in the database.
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            if (newIds.contains(existing.Id)) {
                // Skip records that are part of this save (handled below / self).
                continue;
            }
            existingKeys.add(buildKey(existing.AccountId, existing.Email));
        }

        // Iterate candidates in order: first occurrence wins, later ones fail.
        for (Contact con : candidates) {
            String key = buildKey(con.AccountId, con.Email);
            if (existingKeys.contains(key)) {
                con.addError(ERROR_MESSAGE);
            } else {
                existingKeys.add(key);
            }
        }
    }

    private String buildKey(Id accountId, String email) {
        return accountId + '|' + email.trim().toLowerCase();
    }
}
