/**
 * Singleton that performs the shared parent-Account query for Contact trigger actions.
 *
 * The inner `Service` class is registered as the first before-insert trigger action so
 * that it (re)loads `accountsById` once per trigger execution. Later actions then read
 * from the cached map instead of querying Accounts themselves, guaranteeing exactly one
 * Account query per trigger execution shared by every action.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /**
     * Parent Accounts for the Contacts in the current trigger execution, keyed by Id.
     */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that loads the shared parent-Account map. Registered with the lowest
     * Order__c so it runs before the actions that consume the map. It reloads the map on
     * every trigger execution because later DML in the same transaction can involve other
     * Accounts.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact con : (List<Contact>) triggerNew) {
                if (con.AccountId != null) {
                    accountIds.add(con.AccountId);
                }
            }

            Map<Id, Account> accountsById = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                accountsById = new Map<Id, Account>(
                    [
                        SELECT
                            Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = accountsById;
        }
    }
}
